import os, json
from playwright.sync_api import sync_playwright
u='file://'+os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','index.html'))
res=[]
def ok(name,cond,extra=''): res.append(('PASS' if cond else 'FAIL',name,str(extra)[:110] if not cond else ''))
with sync_playwright() as p:
    b=p.chromium.launch()
    def new():
        ctx=b.new_context(viewport={'width':1280,'height':900},accept_downloads=True); pg=ctx.new_page(); errs=[]
        pg.on('pageerror',lambda e:errs.append(str(e))); pg.on('dialog',lambda d:d.accept())
        pg.goto(u); pg.wait_for_timeout(250); return ctx,pg,errs
    toast=lambda pg: pg.locator('#toast').inner_text()
    def attempt(name,fn):
        try: fn()
        except Exception as ex: res.append(('FAIL',name,str(ex).split('\n')[0][:110]))
    # row menu actions
    ctx,pg,errs=new(); pg.click('[data-act=role][data-role=admin]'); pg.click('[data-act=atab][data-tab=missions]')
    def menu():
        n0=pg.locator('#mbody tr').count()
        pg.locator('details.menu summary').nth(3).click(); pg.locator('details[open] [data-act=editMission]').click(); ok('menu: Edit opens editor', pg.locator('#preview').count()==1); pg.click('[data-act=editorCancel]')
        pg.locator('details.menu summary').nth(3).click(); pg.locator('details[open] [data-act=dupMission]').click(); ok('menu: Duplicate adds a draft row', pg.locator('#mbody tr').count()==n0+1)
        pg.locator('details.menu summary').nth(3).click(); pg.locator('details[open] [data-act=pin]').click(); ok('menu: Pin moves it to top with pin icon', pg.locator('#mbody tr:first-child b svg.ic').count()==1)
        pg.locator('details.menu summary').nth(3).click(); pg.locator('details[open] [data-act=copyLink]').click(); pg.wait_for_timeout(200); ok('menu: Copy link gives feedback', 'copied' in toast(pg).lower() or '?mission=' in toast(pg), toast(pg)); ok('menu closes after action', pg.locator('details.menu[open]').count()==0)
        n1=pg.locator('#mbody tr').count(); pg.locator('details.menu summary').nth(5).click(); pg.locator('details[open] [data-act=delMission]').click(); ok('menu: Delete removes row', pg.locator('#mbody tr').count()==n1-1)
        pg.locator('details.menu summary').first.click(); pg.keyboard.press('Escape'); ok('Escape closes menu', pg.locator('details.menu[open]').count()==0)
        pg.locator('details.menu summary').first.click(); pg.click('#mq'); ok('Outside click closes menu', pg.locator('details.menu[open]').count()==0)
        pg.locator('[data-act=toggleMission]').first.click(); ok('status switch toggles', 'draft' in toast(pg).lower() or 'active' in toast(pg).lower())
        with pg.expect_download() as d: pg.click('button:has-text("Export missions")')
        data=json.load(open(d.value.path())); ok('Export missions downloads valid JSON', isinstance(data,list) and len(data)>5)
        pg.set_input_files('input[type=file]', d.value.path()); pg.wait_for_timeout(200); ok('Import missions accepts the file', 'imported' in toast(pg).lower(), toast(pg))
        pg.fill('#mq','zzzz'); ok('search with no match shows message', 'No missions match' in pg.locator('#mbody').inner_text())
        pg.fill('#mq',''); pg.select_option('#mstatus','draft'); ok('status filter works', pg.locator('#mbody tr').count()>=1)
    attempt('menu',menu); ok('no JS errors (missions)', not errs, errs); ctx.close()
    # editor
    ctx,pg,errs=new(); pg.click('[data-act=role][data-role=admin]'); pg.click('[data-act=atab][data-tab=missions]')
    def ed():
        pg.click('[data-act=newMission]'); pg.click('[data-act=pickTemplate][data-v=survey]')
        pg.click('button[data-act=editorSave]:not([data-draft])'); ok('Publish with empty title is blocked', 'title' in toast(pg).lower(), toast(pg))
        pg.fill('#f-title','T'); pg.fill('#qt-0','First q'); pg.click('[data-act=addQ]'); pg.fill('#qt-1','Second q')
        pg.locator('[data-act=moveQ][data-d="-1"]').nth(1).click(); ok('Move question up', pg.locator('#qt-0').input_value()=='Second q')
        pg.locator('[data-act=moveQ][data-d="1"]').first.click(); ok('Move question down', pg.locator('#qt-1').input_value()=='Second q')
        pg.locator('[data-act=delQ]').first.click(); ok('Remove question', pg.locator('[data-act=delQ]').count()==1)
        pg.click('[data-act=draftSet][data-k=visibility][data-v=segments]'); pg.click('button[data-act=editorSave]:not([data-draft])'); ok('Segments with none chosen is blocked', 'segment' in toast(pg).lower(), toast(pg))
        pg.check('input[data-act=draftSeg][data-seg=Elite]'); pg.click('button[data-act=editorSave]:not([data-draft])'); ok('Publish succeeds', 'live' in toast(pg).lower(), toast(pg))
        pg.click('[data-act=newMission]'); pg.select_option('#copyfrom','g2'); pg.click('[data-act=copyFrom]'); ok('Copy existing mission', '(copy)' in pg.locator('#f-title').input_value())
        pg.click('[data-act=editorSave][data-draft]'); ok('Save as draft works', 'draft' in toast(pg).lower(), toast(pg))
        pg.click('[data-act=newMission]'); pg.click('[data-act=editorCancel]'); ok('Cancel from chooser', pg.locator('#mbody').count()==1)
    attempt('editor',ed); ok('no JS errors (editor)', not errs, errs); ctx.close()
    # rewards / badges / levels
    ctx,pg,errs=new()
    pg.check('input[data-seg=Elite]'); pg.uncheck('input[data-seg=Elite]')
    pg.evaluate("""()=>{const s=JSON.parse(localStorage.getItem('mission-board.v2'));s.ledger.push({id:'bonus',ts:Date.now(),memberId:'me',missionId:'g2',status:'awarded',points:500,proof:'',answers:null,reason:'',decidedAt:Date.now()});localStorage.setItem('mission-board.v2',JSON.stringify(s));}""")
    pg.reload(); pg.wait_for_timeout(250)
    def rw():
        pg.click('[data-act=tab][data-tab=rewards]'); pg.locator('button[data-act=redeem]:not([disabled])').first.click(); ok('Redeem requests a reward', 'requested' in toast(pg).lower(), toast(pg))
        ok('Request appears under Your requests', pg.locator('li:has-text("Requested")').count()>=1)
        pg.locator('button[data-act=redeem]:not([disabled])').first.click()
        pg.click('[data-act=role][data-role=admin]'); pg.click('[data-act=atab][data-tab=incentives]'); pg.click('[data-act=incPending]')
        pg.locator('[data-act=fulfill]').first.click(); ok('Mark delivered', 'delivered' in toast(pg).lower())
        pg.locator('[data-act=decline]').first.click(); ok('Decline and refund', 'returned' in toast(pg).lower() or 'refund' in toast(pg).lower())
        pg.click('[data-act=incTab][data-v=rewards]')
        pg.locator('[data-act=editReward]').first.click(); pg.fill('#rf-title','Renamed reward'); pg.click('dialog button:has-text("Save reward")'); ok('Edit reward saves', pg.locator('tbody tr:has-text("Renamed reward")').count()==1)
        pg.locator('[data-act=toggleReward]').first.click(); ok('Reward active switch', pg.locator('[data-act=toggleReward]').first.get_attribute('aria-checked')=='false')
        c=pg.locator('[data-act=delReward]').count(); pg.locator('[data-act=delReward]').last.click(); ok('Delete reward', pg.locator('[data-act=delReward]').count()==c-1)
        pg.click('[data-act=incTab][data-v=badges]')
        pg.locator('[data-act=editBadge]').first.click(); pg.click('dialog button:has-text("Save badge")'); ok('Edit badge saves', 'saved' in toast(pg).lower(), toast(pg))
        pg.locator('[data-act=toggleBadge]').first.click(); ok('Badge active switch', True)
        pg.locator('[data-act=giveBadge]').first.click(); ok('Award manual badge', 'awarded' in toast(pg).lower(), toast(pg))
        c=pg.locator('[data-act=delBadge]').count(); pg.locator('[data-act=delBadge]').last.click(); ok('Delete badge', pg.locator('[data-act=delBadge]').count()==c-1)
        pg.click('[data-act=incTab][data-v=levels]'); c=pg.locator('[data-act=delLevel]').count(); pg.click('[data-act=addLevel]'); ok('Add level', pg.locator('[data-act=delLevel]').count()==c+1)
        pg.click('button:has-text("Save levels")'); ok('Save levels', 'saved' in toast(pg).lower(), toast(pg))
        pg.locator('[data-act=delLevel]').last.click(); ok('Remove level', pg.locator('[data-act=delLevel]').count()==c)
        pg.click('[data-act=atab][data-tab=settings]'); pg.click('[data-act=copyEmbed]'); pg.wait_for_timeout(150); ok('Copy embed code gives feedback', 'cop' in toast(pg).lower(), toast(pg))
        pg.click('[data-act=reset]'); ok('Reset demo data', 'reset' in toast(pg).lower())
    attempt('rewards',rw); ok('no JS errors (rewards/badges/levels)', not errs, errs); ctx.close()
    # member flows
    ctx,pg,errs=new()
    def mem():
        pg.click('button.item:has-text("Join your vertical forums")'); pg.click('dialog button:has-text("Submit survey")'); ok('Survey: required enforced', 'required' in pg.locator('dialog .errmsg').inner_text().lower())
        pg.keyboard.press('Escape'); ok('Escape closes the sheet', pg.locator('dialog[open]').count()==0)
        pg.check('input[data-seg=Advocates]'); pg.click('button.item:has-text("G2 review")'); pg.fill('#proof','not a link'); pg.click('dialog button:has-text("Submit for review")')
        ok('Proof: invalid link rejected', pg.locator('dialog[open]').count()==1)
        pg.fill('#proof','https://www.g2.com/products/x/reviews/1'); pg.click('dialog button:has-text("Submit for review")'); ok('Proof: valid link submits', 'review' in toast(pg).lower(), toast(pg))
        pg.click('[data-act=tab][data-tab=activity]'); ok('My activity shows it', 'In review' in pg.locator('.body').inner_text())
        pg.click('[data-act=tab][data-tab=board]'); ok('Leaderboard renders', pg.locator('.rank').count()>=3)
        pg.click('[data-act=tab][data-tab=missions]'); pg.click('[data-act=cat][data-v=Learn]'); ok('Category filter', pg.locator('.group h2').count()==1)
        pg.click('[data-act=status][data-v=done]'); pg.click('[data-act=status][data-v=all]'); pg.click('[data-act=cat][data-v=all]'); ok('Status/category reset', pg.locator('.group h2').count()>=3)
        pg.locator('button.upcard').first.click(); ok('Up next card opens mission', pg.locator('dialog[open]').count()==1)
        pg.click('dialog [data-act=closeDlg]'); ok('Close button works', pg.locator('dialog[open]').count()==0)
        pg.click('dialog' if False else '[data-act=role][data-role=admin]'); pg.click('[data-act=role][data-role=member]'); ok('Role switch back and forth', pg.locator('.hero').count()==1)
    attempt('member',mem); ok('no JS errors (member)', not errs, errs); ctx.close()
    ctx,pg,errs=new(); pg.goto(u+'?embed=1&mission=forum-product'); pg.wait_for_timeout(250); ok('Deep link opens the mission', pg.locator('dialog[open]').count()==1); ctx.close()
    ctx,pg,errs=new(); pg.click('[data-act=role][data-role=admin]'); pg.click('[data-act=atab][data-tab=approvals]')
    def ap():
        pg.locator('button[data-act=approve]').first.click(); ok('Approve one', 'approved' in toast(pg).lower())
        pg.locator('button[data-act=reject]').first.click(); pg.click('[data-act=cancelDecline]'); ok('Cancel decline', pg.locator('input[id^=why-]').count()==0)
        ok('external links open safely', pg.locator('a[target=_blank]:not([rel*=noopener])').count()==0)
        pg.click('[data-act=atab][data-tab=ledger]'); with_dl=None
        with pg.expect_download() as d: pg.click('[data-act=exportCsv]')
        ok('Ledger CSV downloads', d.value.suggested_filename.endswith('.csv'))
    attempt('approvals',ap); ok('no JS errors (approvals)', not errs, errs); ctx.close()
    b.close()
for r in res: print(*r)
f=[r for r in res if r[0]=='FAIL']; print('\n%d checks, %d failed'%(len(res),len(f)))
raise SystemExit(1 if f else 0)
